'use client';

import React from 'react';

/** Visual variant for the PromptSuggestions container. */
export type PromptSuggestionsVariant = 'chips';

/** A single prompt suggestion item. */
export interface PromptSuggestionItem {
  /** Unique identifier. */
  value: string;
  /** Suggestion text. */
  text: string;
  /** Optional icon displayed above the text. */
  icon?: string;
}

/** A labelled group of suggestions. */
export interface PromptSuggestionGroup {
  /** Group heading. */
  label: string;
  /** Items in this group. */
  items: PromptSuggestionItem[];
}

/** Props for the {@link PromptSuggestions} component. */
export interface PromptSuggestionsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onSelect'> {
  /** Flat array of suggestions (use this OR `groups`). */
  suggestions?: PromptSuggestionItem[];
  /** Categorized groups of suggestions (takes precedence over `suggestions`). */
  groups?: PromptSuggestionGroup[];
  /** Label text displayed above the grid. */
  label?: string;
  /** Visual variant. */
  variant?: PromptSuggestionsVariant;
  /** Called when a suggestion is selected. */
  onSelect?: (value: string) => void;
  /** Show a keyboard-hint footer (↑↓ navigate · ↵ select). */
  showKeyboardHints?: boolean;
  /** Opt into the staggered entrance animation. */
  animate?: boolean;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * Starter prompt suggestions for an empty AI chat state. Renders a grid (or
 * chips, or labelled groups) of clickable suggestions with arrow-key roving
 * focus and Enter/Space activation.
 */
export const PromptSuggestions = React.forwardRef<HTMLDivElement, PromptSuggestionsProps>(
  (
    { suggestions, groups, label, variant, onSelect, showKeyboardHints, animate, className, ...rest },
    ref,
  ) => {
    const flat = React.useMemo<PromptSuggestionItem[]>(
      () => (groups ? groups.flatMap((g) => g.items) : suggestions ?? []),
      [groups, suggestions],
    );
    const btnRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
    const [focused, setFocused] = React.useState(-1);

    const focusAt = React.useCallback(
      (i: number) => {
        const n = flat.length;
        if (n === 0) return;
        const idx = ((i % n) + n) % n;
        setFocused(idx);
        btnRefs.current[idx]?.focus();
      },
      [flat.length],
    );

    const handleKeyDown = React.useCallback(
      (e: React.KeyboardEvent<HTMLDivElement>) => {
        if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
          e.preventDefault();
          focusAt(focused + 1);
        } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
          e.preventDefault();
          focusAt(focused - 1);
        }
      },
      [focused, focusAt],
    );

    // running index across (optionally grouped) items, in flat order
    let index = -1;
    const renderItem = (s: PromptSuggestionItem) => {
      index += 1;
      const i = index;
      return (
        <button
          key={s.value}
          ref={(el) => {
            btnRefs.current[i] = el;
          }}
          type="button"
          className="sk-prompt-suggestion"
          data-focused={focused === i ? '' : undefined}
          onClick={() => onSelect?.(s.value)}
          onFocus={() => setFocused(i)}
        >
          {s.icon && <span className="sk-prompt-suggestion__icon">{s.icon}</span>}
          <span className="sk-prompt-suggestion__text">{s.text}</span>
        </button>
      );
    };

    return (
      <div
        ref={ref}
        className={`sk-prompt-suggestions${className ? ` ${className}` : ''}`}
        data-variant={variant}
        data-animate={animate ? '' : undefined}
        onKeyDown={handleKeyDown}
        {...rest}
      >
        {label && <span className="sk-prompt-suggestions__label">{label}</span>}
        {groups ? (
          groups.map((g) => (
            <div key={g.label} className="sk-prompt-suggestions__group">
              <span className="sk-prompt-suggestions__group-label">{g.label}</span>
              <div className="sk-prompt-suggestions__grid">{g.items.map(renderItem)}</div>
            </div>
          ))
        ) : (
          <div className="sk-prompt-suggestions__grid">{(suggestions ?? []).map(renderItem)}</div>
        )}
        {showKeyboardHints && (
          <div className="sk-prompt-suggestions__hint" aria-hidden="true">
            {'↑↓'} navigate · {'↵'} select
          </div>
        )}
      </div>
    );
  },
);

PromptSuggestions.displayName = 'PromptSuggestions';

/**
 * skeehn — PromptSuggestions Component
 *
 * @component sk-prompt-suggestions
 * @variants  default | chips
 * @slots     __label __grid __group __icon __text (+ sk-prompt-suggestion)
 * @a11y      Keyboard navigable, focus rings, button semantics
 * @design    2-3 col grid, readable label, prominent icons, lift-on-hover.
 */

.sk-prompt-suggestions { display: flex; flex-direction: column; gap: var(--sk-space-3); padding: var(--sk-space-6) 0; }
.sk-prompt-suggestions__label {
  font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs); font-weight: 700;
  letter-spacing: var(--sk-letter-spacing-xwide); text-transform: uppercase;
  color: hsl(var(--sk-muted-foreground));
}
.sk-prompt-suggestions__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: var(--sk-space-2); }

.sk-prompt-suggestion {
  border: var(--sk-border); border-radius: var(--sk-radius-md);
  padding: var(--sk-space-3) var(--sk-space-4);
  font-family: var(--sk-font-sans); font-size: var(--sk-font-size-sm);
  color: hsl(var(--sk-foreground)); background: hsl(var(--sk-surface));
  cursor: pointer; text-align: left; line-height: var(--sk-line-height);
  transition: border-color var(--sk-transition), background var(--sk-transition), transform var(--sk-transition-fast);
  position: relative; overflow: hidden;
}
.sk-prompt-suggestion::before {
  content: ""; position: absolute; inset: 0;
  background-image: var(--sk-dither-pattern); background-size: 8px 8px;
  opacity: 0; transition: opacity var(--sk-transition); pointer-events: none;
}
.sk-prompt-suggestion:hover { border-color: hsl(var(--sk-accent)); background: hsl(var(--sk-secondary)); transform: translateY(-1px); }
.sk-prompt-suggestion:hover::before { opacity: var(--sk-dither-opacity-subtle); }
.sk-prompt-suggestion:active { transform: translateY(0); }
.sk-prompt-suggestion:focus-visible { outline: var(--sk-focus-ring); outline-offset: var(--sk-focus-ring-offset); }

.sk-prompt-suggestion__icon { display: block; font-family: var(--sk-font-mono); font-size: 1.1rem; margin-bottom: var(--sk-space-2); color: hsl(var(--sk-accent)); }
.sk-prompt-suggestion__text { display: block; position: relative; z-index: 1; }

/* Chips variant */
.sk-prompt-suggestions[data-variant="chips"] .sk-prompt-suggestions__grid { grid-template-columns: none; display: flex; flex-wrap: wrap; }
.sk-prompt-suggestions[data-variant="chips"] .sk-prompt-suggestion { padding: var(--sk-space-1) var(--sk-space-3); font-size: var(--sk-font-size-xs); font-family: var(--sk-font-mono); border-radius: var(--sk-radius-full); }
.sk-prompt-suggestions[data-variant="chips"] .sk-prompt-suggestion__icon { display: none; }

/* Categorized groups */
.sk-prompt-suggestions__group { display: flex; flex-direction: column; gap: var(--sk-space-2); }
.sk-prompt-suggestions__group-label {
  font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs); font-weight: 700;
  letter-spacing: var(--sk-letter-spacing-wide); text-transform: uppercase;
  color: hsl(var(--sk-muted-foreground) / 0.75);
  padding-bottom: var(--sk-space-1); border-bottom: 1px dashed hsl(var(--sk-border-color));
}

/* Staggered entrance */
@keyframes sk-suggestion-enter { from { transform: translateY(8px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
.sk-prompt-suggestions[data-animate] .sk-prompt-suggestion { opacity: 0; animation: sk-suggestion-enter var(--sk-anim-normal, 300ms) var(--sk-ease-pixel) both; }
.sk-prompt-suggestions[data-animate] .sk-prompt-suggestion:nth-child(1) { animation-delay: 0ms; }
.sk-prompt-suggestions[data-animate] .sk-prompt-suggestion:nth-child(2) { animation-delay: 60ms; }
.sk-prompt-suggestions[data-animate] .sk-prompt-suggestion:nth-child(3) { animation-delay: 120ms; }
.sk-prompt-suggestions[data-animate] .sk-prompt-suggestion:nth-child(4) { animation-delay: 180ms; }
.sk-prompt-suggestions[data-animate] .sk-prompt-suggestion:nth-child(5) { animation-delay: 240ms; }
.sk-prompt-suggestions[data-animate] .sk-prompt-suggestion:nth-child(6) { animation-delay: 300ms; }

/* Keyboard focus */
.sk-prompt-suggestion[data-focused] { border-color: hsl(var(--sk-accent)); background: hsl(var(--sk-secondary)); }

/* Keyboard hint footer */
.sk-prompt-suggestions__hint {
  font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-muted-foreground) / 0.7);
  letter-spacing: var(--sk-letter-spacing-wide); text-align: center;
  margin-top: var(--sk-space-1);
}

/* Loading & skeleton */
.sk-prompt-suggestions[data-loading] .sk-prompt-suggestion { pointer-events: none; opacity: 0.5; }
.sk-prompt-suggestions[data-skeleton] .sk-prompt-suggestion {
  pointer-events: none; color: transparent;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-secondary)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%; animation: sk-shimmer 1.8s ease-in-out infinite; min-height: 3rem;
}
.sk-prompt-suggestions[data-skeleton] .sk-prompt-suggestion::before { display: none; }

@media print { .sk-prompt-suggestions { display: none; } }
@media (prefers-reduced-motion: reduce) {
  .sk-prompt-suggestion, .sk-prompt-suggestion::before { transition: none; }
  .sk-prompt-suggestion:active, .sk-prompt-suggestion:hover { transform: none; }
  .sk-prompt-suggestions[data-animate] .sk-prompt-suggestion { animation: none; opacity: 1; }
  .sk-prompt-suggestions[data-skeleton] .sk-prompt-suggestion { animation: none; background: hsl(var(--sk-muted)); }
}
